import math
def control(obs):
    m=obs.get('local_map',{})
    def interp(points,x):
        p=sorted((a,b) for a,b in points)
        for (a,b),(c,d) in zip(p,p[1:]):
            if a<=x<=c and c>a:
                return b+(d-b)*(x-a)/(c-a)
        return None
    x=4.0
    l=interp(m.get('left_rail',[]),x)
    r=interp(m.get('right_rail',[]),x)
    if l is None or r is None:
        x=2.5
        l=interp(m.get('left_rail',[]),x)
        r=interp(m.get('right_rail',[]),x)
    center=(l+r)/2 if l is not None and r is not None else 0
    desired=max(-24,min(24,math.degrees(math.atan2(center,x))*1.1))
    hitch=obs.get('hitch_deg',0)
    steer=max(-34,min(34,2.0*(hitch-desired)))
    return (steer,-0.8,180)

