import math

def interp(points, x):
    p=sorted((a,b) for a,b in points)
    for i in range(len(p)-1):
        if p[i][0] <= x <= p[i+1][0]:
            d=p[i+1][0]-p[i][0]
            if d>0.01: return p[i][1]+(p[i+1][1]-p[i][1])*(x-p[i][0])/d
    return None

def control(obs):
    m=obs.get('local_map',{})
    l=m.get('left_rail',[])
    r=m.get('right_rail',[])
    vals=[]
    for x in (2,3,4,5,6,7,8):
        a=interp(l,x); b=interp(r,x)
        if a is not None and b is not None: vals.append((x,(a+b)/2))
    if vals:
        x,y=vals[-1]
        desired=max(-25,min(25,math.degrees(math.atan2(y,x))*1.4))
    else: desired=0
    hitch=obs.get('hitch_deg',0)
    steer=max(-38,min(38,1.8*(hitch-desired)))
    return steer,-0.8,180

