import math

def control(obs):
    m=obs.get('local_map',{})
    left=m.get('left_rail',[])
    right=m.get('right_rail',[])
    def at(points,u):
        pts=sorted((p[0],p[1]) for p in points if len(p)>=2)
        for a,b in zip(pts,pts[1:]):
            if a[0]<=u<=b[0] and b[0]-a[0]<5:
                return a[1]+(b[1]-a[1])*(u-a[0])/(b[0]-a[0])
        return None
    centers=[]
    for u in (3,6,9,12,15,18):
        l=at(left,u); r=at(right,u)
        if l is not None and r is not None:
            centers.append((u,(l+r)/2))
    target=0.0
    if centers:
        w=sum(u for u,c in centers)
        target=sum(u*c for u,c in centers)/w
    desired=max(-12,min(12,math.degrees(math.atan2(target,12))*1.5))
    hitch=obs.get('hitch_deg',0)
    steer=max(-35,min(35,2.0*(hitch-desired)))
    return (steer,-1.1,180)

